INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("春咲 ひより", 2, 0, 0, 1, 0, 0, 1, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", "お！\nあそこに困ってそうな人発見！", 1001, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("草野 優衣", 2, 0, 0, 1, 0, 0, 1, "わ、わたし、\nなに言ってるんだろ\nあはは…", "大切な人を\n守れるようになりたい…って", 1002, "みんなみたいに\nわたしも強くならなきゃ", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("士条 怜", 2, 0, 0, 1, 0, 0, 1, "少しは磨かれると思いますよ。", "キミに必要な集中力と感性が", 1003, "フェンシングを始めてみては？", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("穂高 みそぎ", 2, 0, 0, 1, 0, 0, 1, "みそぎはねぇ、\nかくれんぼやりたい！", "今日はなにして遊ぶ？", 1004, "ねぇ、にいちゃん！", 0, 1.5, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("風宮 あかり", 2, 0, 0, 1, 0, 0, 1, "私といっしょに…\nいかない？", "ねぇ…", 1006, "風宮あかりです", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("出雲 宮子", 2, 0, 0, 1, 0, 0, 1, "食べ物の恨みは怖いのー", "プリンたべたいのー", 1007, "出雲宮子なのー", 0, 1.5, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("虹村 雪", 2, 0, 0, 1, 0, 0, 1, "いいよ。\n見られることは運命さ…", "キミもボクの美貌に\n吸い寄せられたんだね。", 1008, "ボクは虹村雪。", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("柊杏奈", 2, 0, 0, 1, 0, 0, 1, "人呼んで「疾風の冥姫」!!", "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 1009, "フッ…聞いて後悔するがいい！", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("姫宮 真歩", 2, 0, 0, 1, 0, 0, 1, "ほんまおおきにやわ～♪", "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 1010, "マホマホ王国のプリンセス、\nまほ姫どす", 0, 1.5, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("衣之咲 璃乃", 2, 0, 0, 1, 0, 0, 1, "ここで会ったが\n100年目～！", "生き別れたお兄ちゃんを探して\n三千世界！", 1011, "衣之咲璃乃です！", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("柏崎 初音", 2, 0, 0, 1, 0, 0, 1, "…って、お願い！\n誰にも言わないでおいて～！", "ち、超能力って…\n何のことかな～？", 1012, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("美波 鈴奈", 2, 0, 0, 1, 0, 0, 1, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", "一応カリスマ読モJKやってまっす！", 1016, "ちょす！\n美波鈴奈だよ～♪", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("喜屋武 香織", 2, 0, 0, 1, 0, 0, 1, "でも、沖縄もとってもいいとこさー", "東京は遊園地みたいなところさー", 1017, "はいたーい。\n喜屋武香織さー。", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("支倉 伊緒", 2, 0, 0, 1, 0, 0, 1, "イオちゃんって呼んでね。", "先生って呼ばれるのは\nくすぐったいから", 1018, "支倉伊緒です。", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("茜 ミミ", 2, 0, 0, 1, 0, 0, 1, "ミミをおいてかないでぇ～", "あ！/\お兄ちゃ～ん\nまってよ～", 1020, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 0, 1.5, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("栗林 くるみ", 2, 0, 0, 1, 0, 0, 1, "ふぇぇぇぇぇん……", "あの……\nふぇ……", 1021, "あ…あの…えっと…\n栗…林…くるみ…です……", 0, 1.5, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("風宮 より", 2, 0, 0, 1, 0, 0, 1, "なんてありがとうございます！", "こんな私に貴重な時間を\n割いていただき、", 1022, "風宮よりです。\nあああああ！", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("北条 綾音", 2, 0, 0, 1, 0, 0, 1, "私こっち行きたいー\nね、早く早くー", "おにいちゃんどこいくの？\nえ？", 1023, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 0, 1.5, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("天野 すずめ", 2, 0, 0, 1, 0, 0, 1, "これて何か違う…\nあああすみません！", "ふ、不束者ですが\nどうぞ末永く…って、", 1025, "わっ…わっ…私、\n天野すずめといいます！", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("倉石 恵理子", 2, 0, 0, 1, 0, 0, 1, "離しませんわ………\n絶対に…!!", "あなたは…運命の……\n伴侶……", 1027, "……クスクス…私は\n…倉石恵理子……", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("佐々木 咲恋", 2, 0, 0, 1, 0, 0, 1, "…そうでしょ？？", "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 1028, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("桜井 望", 2, 0, 0, 1, 0, 0, 1, "あはは、\n私もまだまだだなぁ～", "ぇっと…\nキミ、私のこと知らないの?!", 1029, "桜井望だよ！\nよろしくねっ", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("ニノン・ジュベール", 2, 0, 0, 1, 0, 0, 1, "ショーグン、\nワタシと一緒に天下統一デース！", "初めまして、\n私はニノン・ジュベール申すデス！", 1030, "デケデケデンっ！", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("上喜 しのぶ", 2, 0, 0, 1, 0, 0, 1, "おかしいですね……", "でもって私の隣にいるのが……\nえ、見えない？", 1031, "上喜しのぶです。\n手元のドクロが父です。", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("野戸まひる", 2, 0, 0, 1, 0, 0, 1, "そう、\nオラのボケに突っ込める相方が…！", "けんども\nそれには足りないモンが…", 1033, "目指すはビッグな\nお笑い芸人だっぺ！", 0, 1.5, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("綾瀬 ゆかり", 2, 0, 0, 1, 0, 0, 1, "ちょ\nちょっと一杯飲んできます…！", "ちょっと緊張しちゃって…", 1034, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("氷川 鏡華", 2, 0, 0, 1, 0, 0, 1, "これ以上お話しすることは…\nないです！", "知らない人とは話しちゃいけないので", 1036, "氷川鏡華…です", 0, 1.5, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("柏崎 栞", 2, 0, 0, 1, 0, 0, 1, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", "……あ、アラーム。", 1038, "柏崎…栞です。", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("双葉 碧", 2, 0, 0, 1, 0, 0, 1, "野に咲く花が、\n唯一の話相手です。", "私、一人も友達がいなくて……", 1040, "ふ、双葉碧です。", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("三角 千歌", 2, 0, 0, 1, 0, 0, 1, "そう思っています。", "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 1042, "三角千歌です。", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("安芸 真琴", 2, 0, 0, 1, 0, 0, 1, "う、疑ってすまなかったな…", "あぁ？\nお前のそいつの仲間か？", 1043, "安芸真琴だ。", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("イリヤ・オーンスタイン", 2, 0, 0, 1, 0, 0, 1, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", "生けとし生ける全ての者よ！", 1044, "わらわこそは夜を総べる者！", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("遠見 空花", 2, 0, 0, 1, 0, 0, 1, "ｌク、クウカに何かご用ですか!?", "ぐふふふふ……はっ！", 1045, "そこで騎士は妖精を乱暴に……", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("宮坂たまき", 2, 0, 0, 1, 0, 0, 1, "う～ん…\n猫ってホントに最高にゃ～♪", "自由気ままで♪\n寝て遊んで、食べてケンカして…", 1046, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("大神 美冬", 2, 0, 0, 1, 0, 0, 1, "…と思ったら\nバイトの時間だ！\nまたあとでね！", "それでは早速クエストに…", 1048, "大神美冬よ！", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("星野静流", 2, 0, 0, 1, 0, 0, 1, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", "クエストもバトルも\n掃除も洗濯も", 1049, "星野静流だよ！", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("玉泉美咲", 2, 0, 0, 1, 0, 0, 1, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", "見ての通りの\nセクシー美少女で", 1050, "アタシは玉泉美咲。", 0, 1.5, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("リマ", 2, 0, 0, 1, 0, 0, 1, "？？？？", "？？？？", 1052, "？？？", 0, 1.4, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("モニカ・ヴァイスヴィント", 2, 0, 0, 1, 0, 0, 1, "そ、そこまでいうなら\nもらってやる", "菓子でつろうなどと\n稚拙な策を……", 1053, "モニカ・ヴァイスヴィントだ。", 0, 1.5, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("ペコリーヌ", 2, 0, 0, 1, 0, 0, 1, "そ、そこまでいうなら\nもらってやる", "菓子でつろうなどと\n稚拙な策を……", 1058, "モニカ・ヴァイスヴィントだ。", 0, 1.5, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("コッコロ", 2, 0, 0, 1, 0, 0, 1, "そ、そこまでいうなら\nもらってやる", "菓子でつろうなどと\n稚拙な策を……", 1059, "モニカ・ヴァイスヴィントだ。", 0, 1.5, 1);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES ("キャル", 2, 0, 0, 1, 0, 0, 1, "そ、そこまでいうなら\nもらってやる", "菓子でつろうなどと\n稚拙な策を……", 1060, "モニカ・ヴァイスヴィントだ。", 0, 1.5, 1);
